export function add(a: number, b: number): number {
  return a + b;
}

export const PI = 3.14159;

export interface Vector {
  x: number;
  y: number;
}

export default function length(v: Vector): number {
  return Math.hypot(v.x, v.y);
}

import length, { add, PI, type Vector } from "./math.js";

const v: Vector = { x: 3, y: 4 };

console.log(add(1, 2), PI, length(v));

